using System.Collections.Generic;
using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

namespace Azure.ResourceManager
{
    [JsonSerializable(typeof(ArmEnvironment))]
    [JsonSerializable(typeof(Dictionary<string, Dictionary<string, JsonElement>>))]
    [JsonSerializable(typeof(Dictionary<string, string>))]
    internal partial class ArmSerializerContext : JsonSerializerContext
    {
    }

    internal static class ResponseErrorSerialization
    {
        private static readonly JsonSerializerOptions s_options = CreateOptions();

        private static JsonSerializerOptions CreateOptions()
        {
            var options = new JsonSerializerOptions();
            options.TypeInfoResolverChain.Add(new DefaultJsonTypeInfoResolver());
            return options;
        }

        internal static void Serialize(Utf8JsonWriter writer, ResponseError error)
        {
            JsonSerializer.Serialize(writer, error, s_options);
        }

        internal static ResponseError Deserialize(string json)
        {
            return JsonSerializer.Deserialize<ResponseError>(json, s_options);
        }
    }
}

